    queries: [
      "Operations Manager Austria",
      "Supply Chain Manager Wien",
      "Logistics Manager Österreich",
      "COO Austria",
      "Head of Operations Wien"
    ]
  }
];

// Calculate which category based on days since start
const startDate = new Date('2025-01-01');
const today = new Date();
const daysSinceStart = Math.floor((today - startDate) / (1000 * 60 * 60 * 24));
const categoryIndex = daysSinceStart % categories.length;

const todaysCategory = categories[categoryIndex];
const nextCategory = categories[(categoryIndex + 1) % categories.length];

return [{
  json: {
    category: todaysCategory.name,
    queries: todaysCategory.queries,
    categoryIndex: categoryIndex,
    nextCategory: nextCategory.name,
    date: today.toISOString().split('T')[0]
  }
}];

const items = $input.all();
const allJobs = [];

// Blacklist
const blacklist = [
  "PSA", "Drees & Sommer", "LKW Walter", "Cyan Security", "Schmachtl",
  "Netconomy", "Lisec", "Babak Bacon", "Binderholz", "Post", "Lat Nitrogen",
  "Still", "ATSP", "KUKA", "Kotanyi", "Eam", "Rohndo Ganahl", "Informatics",
  "Rail Power Systems", "Doka", "Hobex", "Budimex", "ComeOn Group", "Toolsense",
  "Mubea", "XXXL", "Ortner", "Axians", "ARAG", "Planradar", "Haberkorn",
  "Xit Cross", "Würth Elektronik", "Filzwieser", "Tractive", "Bühler",
  "Salesianer", "Lasselsberger", "TaxPro", "Automation X", "Light for the world",
  "Ebcont", "Waterdrop", "Hoerbiger", "Verbund", "Plasmics", "Patchbox", "Feri",
  "Navax", "Uniqa", "Workist", "RBI", "Hahn Software", "Bawag", "Finmatics",
  "Meister", "KIK", "With Solid", "Tink", "UCS", "Mister Specks", "Bitpanda",
  "Speedinvest", "CTRL.QS", "Joris Ide", "Gebr. Heinemann", "Ubimet", "Gekko",
  "Steffl", "Waldquelle", "enspired", "Swat.io", "Consileon", "Glacier",
  "Treetop Medical", "Sclable", "Journi", "Jentis", "Generali", "Otago",
  "Anyline", "Celum", "Frequentis", "Herold", "IBM iX CH DE", "Imi",
  "Voestalpine", "Tourradar", "Mysugr", "Evolve Consulting", "Bet@Home",
  "Alpenland", "Nexxar", "NextMunich", "BWT", "ZKW", "Deepopinion", "Oatly",
  "Eversports", "HalloSonne", "Dynatrace", "Ikarus", "Storyblok", "IKEA", "Mjam"
];

// Recruiting agency keywords
const recruitingKeywords = [
  "recruiting", "staffing", "personalberatung", "headhunter",
  "hr consulting", "personaldienstleister", "zeitarbeit",
  "personalvermittlung", "executive search", "talent acquisition agency",
  "randstad", "hays", "michael page", "robert half", "adecco", "manpower"
];

const jobDescriptionKeywords = [
  "im auftrag unseres kunden",
  "für unseren kunden",
  "im kundenauftrag",
  "unser kunde sucht",
  "für einen kunden"
];

function isBlacklisted(companyName) {
  if (!companyName) return true;
  const nameLower = companyName.toLowerCase();
  return blacklist.some(bl => nameLower.includes(bl.toLowerCase()));
}

function isRecruitingAgency(companyName, jobDescription) {
  if (!companyName) return true;
  const nameLower = companyName.toLowerCase();
  const descLower = (jobDescription || '').toLowerCase();

  const isAgencyName = recruitingKeywords.some(kw => nameLower.includes(kw));
  const isAgencyJob = jobDescriptionKeywords.some(kw => descLower.includes(kw));

  return isAgencyName || isAgencyJob;
}

function isRecentJob(dateString) {
  if (!dateString) return false;
  const twoWeeksAgo = new Date();
  twoWeeksAgo.setDate(twoWeeksAgo.getDate() - 14);

  // Try to parse German date formats
  const germanMonths = {
    'januar': 0, 'februar': 1, 'märz': 2, 'april': 3, 'mai': 4, 'juni': 5,
    'juli': 6, 'august': 7, 'september': 8, 'oktober': 9, 'november': 10, 'dezember': 11,
    'jan': 0, 'feb': 1, 'mär': 2, 'apr': 3, 'jun': 5, 'jul': 6, 'aug': 7, 'sep': 8, 'okt': 9, 'nov': 10, 'dez': 11
  };

  // Check for relative dates
  const lowerDate = dateString.toLowerCase();
  if (lowerDate.includes('heute') || lowerDate.includes('today') || 
      lowerDate.includes('gestern') || lowerDate.includes('yesterday') ||
      lowerDate.includes('vor 1 tag') || lowerDate.includes('1 day ago')) {
    return true;
  }

  // Check for "vor X tagen" pattern
  const daysAgoMatch = lowerDate.match(/(\d+)\s*(tag|day)/i);
  if (daysAgoMatch) {
    const daysAgo = parseInt(daysAgoMatch[1]);
    return daysAgo <= 14;
  }

  return true; // Default to including if we can't parse
}

function extractDomain(companyName) {
  // Simple domain extraction - will be enriched by Apollo
  if (!companyName) return null;
  const cleaned = companyName
    .toLowerCase()
    .replace(/\s*(gmbh|ag|se|kg|og|e\.u\.|& co\.?|corp\.?|inc\.?|ltd\.?|ges\.?m\.?b\.?h\.?|co\.? kg)\s*/gi, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
  return cleaned ? `${cleaned}.at` : null;
}

function cleanCompanyName(name) {
  if (!name) return '';
  return name
    .replace(/\s*(GmbH|AG|SE|KG|OG|e\.U\.|& Co\.?|Corp\.?|Inc\.?|Ltd\.?|Ges\.?m\.?b\.?H\.?|Co\.? KG)\s*/gi, '')
    .replace(/[,.\-–—]+$/, '')
    .trim();
}

function cleanJobTitle(title) {
  if (!title) return '';
  return title
    .replace(/\s*\(m\/w\/d\)\s*/gi, '')
    .replace(/\s*\(w\/m\/d\)\s*/gi, '')
    .replace(/\s*\(d\/m\/w\)\s*/gi, '')
    .replace(/\s*\(all genders\)\s*/gi, '')
    .replace(/\s*\(f\/m\/d\)\s*/gi, '')
    .replace(/\s*[-–—]\s*$/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const seenCompanies = new Set();

for (const item of items) {
  const results = item.json.organic || [];
  const category = item.json.category || $('Category Rotation').first().json.category;

  for (const result of results) {
    const companyName = result.company || result.source || '';
    const jobTitle = result.title || '';
    const jobUrl = result.link || '';
    const snippet = result.snippet || '';
    const date = result.date || '';

    // Skip if blacklisted
    if (isBlacklisted(companyName)) continue;

    // Skip if recruiting agency
    if (isRecruitingAgency(companyName, snippet)) continue;

    // Skip if not recent
    if (!isRecentJob(date)) continue;

    // Skip duplicates
    const companyKey = cleanCompanyName(companyName).toLowerCase();
    if (seenCompanies.has(companyKey)) continue;
    seenCompanies.add(companyKey);

    allJobs.push({
      json: {
        company_name: companyName,
        company_name_clean: cleanCompanyName(companyName),
        company_domain: extractDomain(companyName),
        job_title: jobTitle,
        job_title_clean: cleanJobTitle(jobTitle),
        job_url: jobUrl,
        snippet: snippet,
        posted_date: date,
        category: category,
        scraped_at: new Date().toISOString()
      }
    });
  }
}

// Return max 100 jobs for processing
return allJobs.slice(0, 100);

const orgData = $('Apollo Org Enrichment').first().json;
const jobData = $('Loop Apollo Org').first().json;
const peopleData = $json.people || [];

if (peopleData.length === 0) {
  return [{
    json: {
      ...jobData,
      organization: orgData.organization || {},
      hr_contact_found: false,
      skip_reason: 'No HR contacts found'
    }
  }];
}

// Get the first (most relevant) HR contact
const hrContact = peopleData[0];

return [{
  json: {
    ...jobData,
    organization: orgData.organization || {},
    hr_contact_found: true,
    hr_first_name: hrContact.first_name || '',
    hr_last_name: hrContact.last_name || '',
    hr_full_name: `${hrContact.first_name || ''} ${hrContact.last_name || ''}`.trim(),
    hr_title: hrContact.title || '',
    hr_linkedin_url: hrContact.linkedin_url || '',
    hr_email: hrContact.email || '',
    hr_phone: hrContact.phone_numbers?.[0]?.sanitized_number || '',
    hr_apollo_id: hrContact.id || '',
    employees: orgData.organization?.estimated_num_employees || 0
  }
}];

const prevData = $('IF HR Contact Found').first().json;
const matchData = $json.person || {};

// Check if email is verified
const emailVerified = matchData.email_status === 'verified';
const email = emailVerified ? matchData.email : prevData.hr_email;
const phone = matchData.phone_numbers?.[0]?.sanitized_number || prevData.hr_phone;

return [{
  json: {
    ...prevData,
    hr_email: email,
    hr_phone: phone,
    hr_email_verified: emailVerified,
    enrichment_complete: true
  }
}];

const existingLeads = $('Google Sheets Lookup').all();
const currentLead = $('IF Email Exists').first().json;

// Check if contact was contacted in last 30 days
const thirtyDaysAgo = new Date();
thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

let shouldContact = true;
let reason = '';

for (const existing of existingLeads) {
  const lastContact = existing.json['Letzter Kontakt'];
  if (lastContact) {
    const contactDate = new Date(lastContact);
    if (contactDate >= thirtyDaysAgo) {
      shouldContact = false;
      reason = `Already contacted on ${lastContact}`;
      break;
    }
  }
}

return [{
  json: {
    ...currentLead,
    is_new_lead: existingLeads.length === 0,
    should_contact: shouldContact,
    skip_reason: reason
  }
}];

const items = $input.all();

function cleanCompanyName(name) {
  if (!name) return '';
  return name
    .replace(/\s*(GmbH|AG|SE|KG|OG|e\.U\.|& Co\.?|Corp\.?|Inc\.?|Ltd\.?|Ges\.?m\.?b\.?H\.?|Co\.? KG)\s*/gi, '')
    .replace(/[,.\-–—]+$/, '')
    .trim();
}

function cleanJobTitle(title) {
  if (!title) return '';
  return title
    .replace(/\s*\(m\/w\/d\)\s*/gi, '')
    .replace(/\s*\(w\/m\/d\)\s*/gi, '')
    .replace(/\s*\(d\/m\/w\)\s*/gi, '')
    .replace(/\s*\(all genders\)\s*/gi, '')
    .replace(/\s*\(f\/m\/d\)\s*/gi, '')
    .replace(/\s*[-–—]\s*$/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractFirstName(fullName) {
  if (!fullName) return '';
  return fullName.split(' ')[0];
}

return items.map(item => {
  const data = item.json;
  return {
    json: {
      // Sheet columns
      Datum: new Date().toISOString().split('T')[0],
      Kategorie: data.category || '',
      Firma: cleanCompanyName(data.company_name),
      Mitarbeiter: data.employees || data.organization?.estimated_num_employees || '',
      'Job Titel': cleanJobTitle(data.job_title),
      'Job URL': data.job_url || '',
      Gehalt: '', // To be extracted if available
      'HR Kontakt': data.hr_full_name || '',
      Email: data.hr_email || '',
      Telefon: data.hr_phone || '',
      LinkedIn: data.hr_linkedin_url || '',
      'Weitere Jobs': '',
      Status: 'Neu',
      'Letzter Kontakt': '',
      Notizen: '',
      // Additional data for email template
      vorname: extractFirstName(data.hr_full_name),
      firma_clean: cleanCompanyName(data.company_name),
      job_titel_clean: cleanJobTitle(data.job_title)
    }
  };
});

const items = $input.all();
const categoryData = $('Category Rotation').first().json;
const date = new Date().toISOString().split('T')[0];

// Build leads list for email
let leadsHtml = '';
let leadIndex = 1;

for (const item of items) {
  const data = item.json;
  leadsHtml += `
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
LEAD ${leadIndex}:
🏢 Firma: ${data.Firma || data.firma_clean || ''}
💼 Job: ${data['Job Titel'] || data.job_titel_clean || ''}
💰 Gehalt: ${data.Gehalt || 'Nicht angegeben'}
👥 Mitarbeiter: ${data.Mitarbeiter || ''}
👤 HR: ${data['HR Kontakt'] || ''}
📧 ${data.Email || ''}
📞 ${data.Telefon || 'Nicht verfügbar'}
🔗 ${data['Job URL'] || ''}

→ "${leadIndex} OK" oder "${leadIndex} SKIP"
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`;
  leadIndex++;
}

const emailBody = `Hallo Flavio,

Heute: ${categoryData.category} Jobs

Hier sind die ${items.length} Leads zur Freigabe:
${leadsHtml}

Antworte mit: "1 OK, 2 OK, 3 SKIP, 4 OK" etc.

Morgen: ${categoryData.nextCategory} Jobs

Viele Grüße,
Dein n8n Workflow`;

return [{
  json: {
    subject: `🎯 ${items.length} neue ${categoryData.category} Leads zur Freigabe - ${date}`,
    body: emailBody,
    leads: items.map(i => i.json),
    leadCount: items.length,
    category: categoryData.category,
    nextCategory: categoryData.nextCategory,
    date: date
  }
}];

const reply = ($json.textPlain || $json.snippet || '').toUpperCase();
const approvedLeads = [];
const skippedLeads = [];

// Parse Format: "1 OK, 2 SKIP, 3 OK"
const pattern = /(\d+)\s*(OK|SKIP|JA|NEIN|YES|NO)/gi;
let match;

while ((match = pattern.exec(reply)) !== null) {
  const leadNum = parseInt(match[1]);
  const action = match[2].toUpperCase();

  if (['OK', 'JA', 'YES'].includes(action)) {
    approvedLeads.push(leadNum);
  } else {
    skippedLeads.push(leadNum);
  }
}

return [{
  json: {
    approvedLeads,
    skippedLeads,
    rawReply: reply
  }
}];

const approvalData = $('Parse Reply').first().json;
const leads = $('Build Approval Email').first().json.leads || [];

const approvedIndexes = approvalData.approvedLeads || [];
const approvedLeads = [];

for (const idx of approvedIndexes) {
  const leadIndex = idx - 1; // Convert 1-based to 0-based
  if (leadIndex >= 0 && leadIndex < leads.length) {
    approvedLeads.push({ json: leads[leadIndex] });
  }
}

return approvedLeads.length > 0 ? approvedLeads : [{ json: { noApprovedLeads: true } }];

const now = DateTime.now().setZone('Europe/Vienna');
const hour = now.hour;
const dayOfWeek = now.weekday; // 1=Mon, 7=Sun

// Checks
const isWeekend = dayOfWeek > 5;
const isOutsideHours = hour < 8 || hour >= 18;

if (isWeekend || isOutsideHours) {
  // Calculate next business day at 8am
  let next = now.plus({ days: 1 }).set({ hour: 8, minute: 0, second: 0 });
  while (next.weekday > 5) {
    next = next.plus({ days: 1 });
  }

  return [{
    json: {
      ...$json,
      canSend: false,
      reason: isWeekend ? 'Weekend' : 'Outside business hours',
      scheduleFor: next.toISO()
    }
  }];
}

// Random delay 5-15 minutes
const delayMinutes = Math.floor(Math.random() * 11) + 5;

return [{
  json: {
    ...$json,
    canSend: true,
    delayMinutes,
    sendAt: now.plus({ minutes: delayMinutes }).toISO()
  }
}];

// Reference customers list (excluding blacklisted ones for referrals)
const referenzen = [
  "Drees & Sommer", "Cyan Security", "Schmachtl",
  "Netconomy", "Lisec", "Binderholz", "Post", "Still", "KUKA", "Kotanyi",
  "Rail Power Systems", "Doka", "Hobex", "ComeOn Group", "Toolsense",
  "Mubea", "XXXL", "Ortner", "Axians", "ARAG", "Planradar", "Haberkorn",
  "Würth Elektronik", "Tractive", "Bühler", "Salesianer", "Lasselsberger", "Ebcont"
];

// Shuffle and pick 2 random references
const shuffled = [...referenzen].sort(() => Math.random() - 0.5);

const data = $json;
const vorname = data.vorname || data['HR Kontakt']?.split(' ')[0] || 'Guten Tag';
const jobTitel = data.job_titel_clean || data['Job Titel'] || 'offene Position';
const firma = data.firma_clean || data.Firma || 'Ihr Unternehmen';

const emailBody = `Hallo ${vorname},

ich bin auf Ihre offene ${jobTitel} Position aufmerksam geworden.

Wir bei talentmonkeys sind auf genau solche Positionen spezialisiert und arbeiten rein erfolgsbasiert. Sie zahlen nur bei erfolgreicher Besetzung.

Firmen wie ${shuffled[0]} und ${shuffled[1]} vertrauen bereits auf uns.

Hätten Sie diese Woche kurz Zeit für ein Telefonat?

Beste Grüße
Flavio Arteaga

talentmonkeys GmbH
talentmonkeys.com`;

return [{
  json: {
    ...data,
    emailSubject: jobTitel,
    emailBody: emailBody,
    referenz_1: shuffled[0],
    referenz_2: shuffled[1]
  }
}];
